#include <stdio.h>
#include <stddef.h>

int main(void) {
    int a[] = {10, 20, 30, 40, 50};
    size_t n = sizeof a / sizeof a[0];

    for (size_t i = 0; i < n; i++)          // index form
        printf("%d ", a[i]);
    for (int *p = a; p < a + n; p++)        // walking pointer, end = a + n
        printf("%d ", *p);
    for (size_t i = 0; i < n; i++)          // explicit arithmetic
        printf("%d ", *(a + i));
    printf("\n");

    int *first = &a[1], *last = &a[4];
    ptrdiff_t gap = last - first;           // 3 elements
    printf("gap=%td, bytes=%td\n", gap, (char *)last - (char *)first); // 3, 12
    return 0;
}

