int read_u16(const unsigned char **cur, const unsigned char *end, unsigned *out) {
    if (end - *cur < 2) return -1;            // not enough bytes left
    *out = ((*cur)[0] << 8) | (*cur)[1];      // big-endian
    *cur += 2;                                // advance the cursor
    return 0;
}

